// MQTT ile akıllı ev: sıcaklığı yayınla, lamba komutunu dinle.
#include <WiFi.h>
#include <PubSubClient.h>
#include <DHT.h>

const char* AG_ADI = "EvimWiFi";             // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";            // kendi Wi-Fi parolan
const char* MQTT_SUNUCU = "broker.hivemq.com"; // ücretsiz genel sunucu; kendi sunucunu da yazabilirsin
const char* KONU_SICAKLIK = "ev/salon/sicaklik";
const char* KONU_LAMBA = "ev/salon/lamba";
const int DHT_PIN = 4;
const int LAMBA_PIN = 2;
const unsigned long YAYIN_ARALIGI_MS = 5000;

WiFiClient wifiIstemci;
PubSubClient mqtt(wifiIstemci);
DHT dht(DHT_PIN, DHT22);
unsigned long sonYayin = 0;

// Abone olunan konuya mesaj gelince çağrılır.
void mesajGeldi(char* konu, byte* veri, unsigned int uzunluk) {
  String mesaj;
  for (unsigned int i = 0; i < uzunluk; i++) mesaj += (char)veri[i];
  Serial.printf("Mesaj: %s = %s\n", konu, mesaj.c_str());
  if (String(konu) == KONU_LAMBA) {
    if (mesaj == "ac") digitalWrite(LAMBA_PIN, HIGH);
    if (mesaj == "kapat") digitalWrite(LAMBA_PIN, LOW);
  }
}

void mqttBaglan() {
  while (!mqtt.connected()) {
    Serial.print("MQTT'ye baglaniyor... ");
    if (mqtt.connect("kendinyap-esp32")) {
      Serial.println("tamam");
      mqtt.subscribe(KONU_LAMBA);
    } else {
      Serial.println("olmadi, 2 sn sonra tekrar");
      delay(2000);
    }
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(LAMBA_PIN, OUTPUT);
  dht.begin();
  WiFi.begin(AG_ADI, PAROLA);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Wi-Fi tamam, IP: ");
  Serial.println(WiFi.localIP());
  mqtt.setServer(MQTT_SUNUCU, 1883);
  mqtt.setCallback(mesajGeldi);
}

void loop() {
  if (!mqtt.connected()) mqttBaglan();
  mqtt.loop();
  if (millis() - sonYayin > YAYIN_ARALIGI_MS) {
    sonYayin = millis();
    float sicaklik = dht.readTemperature();
    if (!isnan(sicaklik)) {
      String deger = String(sicaklik, 1);
      mqtt.publish(KONU_SICAKLIK, deger.c_str());
      Serial.printf("Yayinlandi: %s = %s\n", KONU_SICAKLIK, deger.c_str());
    }
  }
}
